4. Öffnen Sie `index.js` und fügen Sie folgendes Code hinzu:

```javascript
const { Client, Intents } = require('discord.js');
const { DISCORD_TOKEN } = require('./.env');

const client = new Client({
  intents: [
    Intents.FLAGS.GUILDS,
    Intents.FLAGS.GUILD_MEMBERS,
    Intents.FLAGS.GUILD_BANS,
    Intents.FLAGS.GUILD_MESSAGES,
    Intents.FLAGS.DIRECT_MESSAGES,
  ],
});

client.on('ready', () => {
  console.log(`Bot ${client.user.tag} is ready!`);
});

client.on('messageCreate', async (message) => {
  if (!message.content.startsWith('slash:/ban') || !message.guild) return;

  const member = message.mentions.members.first();
  if (!member) {
    return message.reply('Bitte nenne einen Mitglied, das gebannt werden soll.');
  }

  await message.member.permissions.has('BanMembers')
    ? member.ban()
    : message.reply('Du hast keine Berechtigung, dieses Mitglied zu bannen.');

  message.reply(`${member.user.tag} wurde gebannt.`);
});

client.login(DISCORD_TOKEN);
```

