const { Command } = require('discord.js-commando');

module.exports = class BanCommand extends Command {
  constructor(client) {
    super(client, {
      name: 'ban',
      group: 'moderation',
      memberName: 'ban',
      description: 'Bans a user from the server.',
      guildOnly: true,
      options: [
        {
          name: 'user',
          description: 'The user to ban.',
          type: 'USER',
          required: true,
        },
      ],
    });
