10. Erstellen Sie eine neue Datei mit dem Namen `scripts/compile-commands.js` und fügen Sie folgendes Code hinzu:

```javascript
const { CommandRegistry } = require('discord.js-commando');
const { readFileSync } = require('fs');
const { join } = require('path');

const commandsPath = join(__dirname, 'commands');

const registry = new CommandRegistry();
registry.registerCommandsIn(commandsPath);

const commands = registry.commands.map((command) => {
  const { name, guildOnly } = command;
  const filePath = join(commandsPath, `${name}.js`);

  const content = readFileSync(filePath, 'utf8');
  const source = `module.exports = class ${command.group}${name}Command extends Command {
    constructor(client) {
      super(client, {
        name: '${name}',
        group: '${command.group}',
        memberName: '${name}',
        description: '${command.description}',
        guildOnly: ${guildOnly},
        ${command.options
          .map(
            (option) => `options: [
              {
                name: '${option.name}',
                description: '${option.description}',
                type: '${option.type}',
                ${option.required ? '' : 'required: false,'}
              },
            ]`
          )
          .join('\n')}
      });
    }

    async run(${command.options
      .map((option) => option.name)
      .join(', ')}) {
      ${content}
    }
  };`;

  return { filePath, source };
});

commands.forEach(({ filePath, source }) => {
  require('fs').writeFileSync(filePath, source);
});
```

